/* Сервер — источник баланса и истории. Существующее browser-save остается кешем текущей игры. */
const Player={economy:null,profile:null,signedIn:false,revision:0,confirmedRun:0,timer:null,queue:Promise.resolve(),status:'loading',
 async api(path,options={}){const r=await fetch('/api/'+path,{credentials:'same-origin',headers:{'Content-Type':'application/json'},...options});const data=await r.json();if(!r.ok)throw Error(data.error||'Профиль временно недоступен');return data},
 async load(){if(globalThis.TOCHKA_HOSTING?.cloudProfiles===false){this.status='guest';this.signedIn=false;updatePlayerBar();return}try{const data=await this.api('me');this.signedIn=data.signedIn;this.profile=data.profile;this.status=this.profile?'saved':'guest';updatePlayerBar()}catch{this.status='offline';updatePlayerBar()}},
 save(){if(!this.profile||!game.originalRequest)return;clearTimeout(this.timer);this.timer=setTimeout(()=>this.flush(),450)},
 async flush(){clearTimeout(this.timer);if(!this.profile||!game.originalRequest)return;const state=JSON.parse(JSON.stringify(game)),journal=makeJournal(),id=state.runId,revision=this.revision,credits=runCrystals(state);this.queue=this.queue.then(async()=>{try{this.status='saving';updatePlayerBar();const data=await this.api('run',{method:'POST',body:JSON.stringify({id,revision:this.revision,state,journal})});if(game.runId===id){this.revision=data.revision;this.confirmedRun=credits}this.profile.balance=data.balance;this.status='saved';updatePlayerBar()}catch(e){this.status='offline';updatePlayerBar();announce(e.message)}});await this.queue},
 async restore(run){if(moving)return;await this.flush();game={...defaultGame(),...run.state};this.revision=run.revision;this.confirmedRun=runCrystals(game);boardLevelRendered=-1;profilePersist();modalOpen=false;ge('game-modal').hidden=true;renderGame();updatePlayerBar();if(typeof resumeGameMovement==='function')resumeGameMovement();if(game.pendingOcean&&typeof showOcean==='function')showOcean();if(game.pendingReflection&&!game.pendingMovement){const card=cardManifest['Тень ↔ Сила']?.find(c=>c.id===game.pendingReflection.cardId);if(card)showShadowReflection(card)}},
 async refresh(){await this.flush();await this.load()}
};
function ensureRun(){game.runId||=globalThis.crypto?.randomUUID?.()||`run-${Date.now()}-${Math.random().toString(36).slice(2)}`;game.crystalClaims||={}}
function runCrystals(state=game){return Object.values(state.crystalClaims||{}).reduce((n,c)=>n+(Player.economy?.rewards[c.type]||0),0)}
function crystalBalance(){return Player.profile?Math.max(0,Player.profile.balance+runCrystals()-Player.confirmedRun):runCrystals()}
function claimCrystal(source,type,label){ensureRun();if(game.crystalClaims[source]||!(Player.economy?.rewards[type]>0))return false;const before=crystalBalance();game.crystalClaims[source]={type,label,at:new Date().toISOString()};persist();crystalFlight(Player.economy.rewards[type],before);announce(`${label}. +${Player.economy.rewards[type]} 💎`);return true}
function nextGiftHtml(){if(!Player.economy)return '';const balance=crystalBalance(),gifts=Player.economy.gifts.filter(g=>g.available&&(g.deliverable||g.url)).sort((a,b)=>a.cost-b.cost);const gift=gifts.find(g=>g.cost>balance);if(!gifts.length){const planned=[...Player.economy.gifts].sort((a,b)=>a.cost-b.cost)[0];return planned?`<p>💎 ${Math.min(balance,planned.cost)} / ${planned.cost} · До планируемой первой награды: ${Math.max(0,planned.cost-balance)} 💎</p><small>Подарки готовятся. Обмен пока недоступен.</small>`:'<p>Подарки готовятся.</p>'}return gift?`<p>💎 ${balance} / ${gift.cost} · До «${escapeHtml(gift.title)}» осталось ${gift.cost-balance} 💎</p>`:'<p>У тебя достаточно Кристаллов для подарка. Загляни в Сокровищницу.</p>'}
function updatePlayerBar(){const b=ge('player-crystals');if(!b)return;b.textContent=`💎 ${crystalBalance()}`;ge('player-mode').textContent=Player.profile?(Player.status==='saving'?'Сохраняется…':Player.status==='offline'?'Не синхронизировано':'Профиль сохранен'):'Гость · текущая игра';b.title='Кристаллы накапливаются между играми в профиле и обмениваются на подарки.'}
function crystalFlight(amount,before){updatePlayerBar();game.seenCells||={};if(!game.seenCells.crystal){game.seenCells.crystal=true;profilePersist();const note=document.createElement('div');note.className='crystal-explainer';note.innerHTML=`<p><b>СОБИРАЙ КРИСТАЛЛЫ</b><br>Записывай важные осознания, собирай Кристаллы силы и обменивай их на подарки.</p><div class="gift-previews">${Player.economy.gifts.slice(0,3).map(g=>`<img src="${escapeHtml(g.image)}" alt="${escapeHtml(g.title)}">`).join('')}</div><p>PDF → карточки → марафон → книга → скидка на курс</p><button id="first-crystal-gifts">ПОСМОТРЕТЬ ВСЕ ПОДАРКИ</button><button id="first-crystal-close">Понятно</button>`;document.querySelector('.player-bar').append(note);ge('first-crystal-gifts').onclick=showTreasury;ge('first-crystal-close').onclick=()=>note.remove();}playSound('crystalGain');if(reducedMotion())return;const jewel=document.createElement('span');jewel.className='crystal-flight';jewel.textContent='💎';jewel.setAttribute('aria-hidden','true');const rect=ge('player-crystals').getBoundingClientRect();jewel.style.setProperty('--crystal-x',`${rect.left+rect.width/2-window.innerWidth/2}px`);jewel.style.setProperty('--crystal-y',`${rect.top+rect.height/2-window.innerHeight/2}px`);document.body.append(jewel);setTimeout(()=>jewel.remove(),1100);const started=performance.now();const frame=now=>{const t=Math.min(1,(now-started)/800);ge('player-crystals').textContent=`💎 ${Math.round(before+amount*t)}`;if(t<1)requestAnimationFrame(frame);else updatePlayerBar()};requestAnimationFrame(frame)}
function privacyHtml(){if(globalThis.TOCHKA_HOSTING?.cloudProfiles===false)return '<h3>Мои данные</h3><p>Текущая игра, запрос, ответы, энергия и Кристаллы сохраняются в этом браузере. Ответы не отправляются на сервер и не оцениваются ИИ.</p><p>Облачный профиль и перенос между устройствами пока не подключены. Журнал можно скачать или распечатать. Очистка данных браузера удалит локальное сохранение.</p>';const p=Player.economy.privacy;return `<h3>Как сохраняются данные</h3><p>Ответственный за проект: ${escapeHtml(p.controller)}.${p.contact?` Контакт: ${escapeHtml(p.contact)}.`:' Контакт для вопросов о данных еще не опубликован. Облачное сохранение пока выключено.'}</p><p>При создании профиля сохраняются ID входа, выбранное имя, запросы, ответы, телесные отметки, журналы, прохождения и история Кристаллов. Email для входа обрабатывается системой ChatGPT; игра не использует его для рассылок.</p><p>Цель — продолжение игры, личная история и обмен на настроенные награды. Основание сохранения — твое явное согласие. Ответы могут содержать чувствительные сведения: не записывай данные других людей.</p><p>Профиль и журналы хранятся на сервере Sites с базой Cloudflare D1 до удаления профиля. Доступ к ним ограничен твоим ID входа; информация не публикуется в общем доступе и не передается ИИ для оценки осознаний.</p><p>В профиле можно скачать данные, изменить имя или удалить все сохраненные данные и отозвать согласие. Система входа ChatGPT и инфраструктура хранения имеют собственные правила обработки данных. Технические журналы инфраструктуры не управляются игрой. Ты можешь обратиться в орган по защите данных по месту проживания.</p><p>До подключения профиля текущая игра хранится в этом браузере. Очистка браузера может удалить ее; это не облачный аккаунт.</p><small>Версия ${escapeHtml(p.version)}.</small>`}
function showPrivacy(){showModal('Мои данные','КОНФИДЕНЦИАЛЬНОСТЬ',privacyHtml(),singleClose())}
function giftActionLabel(gift){return gift.type==='download'?'СКАЧАТЬ ПОДАРОК':gift.type==='discount'?'ИСПОЛЬЗОВАТЬ СКИДКУ':'ПОЛУЧИТЬ ДОСТУП'}
async function openOwnedGift(rewardId){try{const d=await Player.api('reward?id='+encodeURIComponent(rewardId));const reward=Player.profile.rewards.find(r=>r.id===rewardId),gift=Player.economy.gifts.find(g=>g.id===reward.reward_id);showModal('МОИ ПОДАРКИ',gift.title,`<p>✓ Получено. Повторное получение не списывает Кристаллы.</p><a class="gift-download" href="${escapeHtml(d.url)}" ${gift.type==='download'?'':'target="_blank" rel="noopener"'}>${giftActionLabel(gift)}</a>`,singleClose())}catch(e){announce(e.message)}}
async function showTreasury(){if(Player.profile)await Player.refresh();const e=Player.economy,balance=crystalBalance();showModal('Подарки твоего пути',e.treasuryTitle,`<p class="treasury-balance">МОИ КРИСТАЛЛЫ: <b>${balance} 💎</b>${Player.profile?'':' · гостевая игра'}</p>${nextGiftHtml()}<div class="gift-grid gift-ladder">${e.gifts.map((g,index)=>{const received=Player.profile?.rewards.find(r=>r.reward_id===g.id),ready=g.available&&(g.deliverable||g.url||g.fileKey),progress=Math.min(balance,g.cost);return `<article class="gift ${received?'gift-received':''}"><span class="gift-step">${index+1} / ${e.gifts.length}</span><img class="gift-image" src="${escapeHtml(g.image)}" alt="${escapeHtml(g.title)}" loading="lazy"><h3>${escapeHtml(g.title)}</h3><p>${escapeHtml(g.description)}</p><b>${g.cost} 💎</b>${received?'<p class="gift-earned">✓ Получено</p>':`<div class="gift-progress"><progress max="${g.cost}" value="${progress}" aria-label="Прогресс до подарка"></progress><p>${progress} / ${g.cost} 💎 · ${balance>=g.cost?'Кристаллов достаточно':`Осталось ${g.cost-balance} 💎`}</p></div>`}<button type="button" data-gift="${g.id}" ${!received&&(!Player.profile||!ready||balance<g.cost)?'disabled':''}>${received?giftActionLabel(g):!ready?'МАТЕРИАЛ ГОТОВИТСЯ':balance<g.cost?'ЕЩЕ НЕДОСТУПНО':`ОБМЕНЯТЬ ${g.cost} 💎`}</button></article>`}).join('')}</div><p class="modal-note">Цены тестовые. Обмен включается после подключения настоящих материалов и профиля. За недоступные подарки Кристаллы не списываются.</p>`,[{label:'Мой профиль',action:showPlayerProfile},{label:'Вернуться к игре',secondary:true,action:closeModal}]);ge('modal-content').querySelectorAll('[data-gift]').forEach(b=>b.onclick=()=>{const received=Player.profile?.rewards.find(r=>r.reward_id===b.dataset.gift);if(received)openOwnedGift(received.id);else confirmGift(b.dataset.gift)})}
function confirmGift(id){const gift=Player.economy.gifts.find(g=>g.id===id);if(!gift?.available||!(gift.deliverable||gift.url||gift.fileKey)||!Player.profile)return;const received=Player.profile.rewards.find(r=>r.reward_id===id);if(received){openOwnedGift(received.id);return}let submitted=false;const operationId=crypto.randomUUID();showModal('Сокровищница','ПОЛУЧИТЬ ПОДАРОК?',`<p>Ты обменяешь ${gift.cost} 💎 на «${escapeHtml(gift.title)}».</p>`,[{label:'ОБМЕНЯТЬ',action:async()=>{if(submitted)return;submitted=true;ge('modal-buttons').querySelectorAll('button').forEach(b=>b.disabled=true);try{const data=await Player.api('redeem',{method:'POST',body:JSON.stringify({rewardId:id,operationId})});Player.profile.balance=data.balance;if(!Player.profile.rewards.some(r=>r.id===data.reward.id))Player.profile.rewards.push(data.reward);updatePlayerBar();playSound('keyActivate');showModal('МОИ ПОДАРКИ',gift.title,`<p>Подарок теперь твой. Он сохранен в профиле.</p><a class="gift-download" href="${escapeHtml(data.url)}" ${gift.type==='download'?'':'target="_blank" rel="noopener"'}>${giftActionLabel(gift)}</a>`,singleClose())}catch(e){submitted=false;ge('modal-buttons').querySelectorAll('button').forEach(b=>b.disabled=false);announce(e.message)}}},{label:'ОТМЕНА',secondary:true,action:showTreasury}])}
async function showPlayerProfile(){if(Player.profile){await Player.refresh();const p=Player.profile;showModal('Моя Точка силы',p.name,`<p><b>💎 ${p.balance}</b> · Завершенных игр: ${p.runs.filter(r=>r.completed).length}</p>${nextGiftHtml()}<h3>Мои прохождения и журналы</h3>${p.runs.map(r=>`<article class="profile-run"><small>${escapeHtml(new Date(r.created_at).toLocaleDateString('ru-RU'))} · ${r.completed?'Путь завершен':'Путь продолжается'}</small><p>${escapeHtml(r.state.originalRequest)}</p><p>${(r.state.completedModules||[]).filter(Boolean).length} из 5 шагов</p><button data-run="${r.id}">Продолжить</button><button data-run-journal="${r.id}">Журнал / печать</button></article>`).join('')||'<p>Первое прохождение появится после ввода запроса.</p>'}<h3>МОИ ПОДАРКИ</h3>${p.rewards.map(r=>`<p>${escapeHtml(r.title)} · ${r.cost} 💎 <button data-reward="${r.id}">Открыть</button></p>`).join('')||'<p>Пока нет полученных наград.</p>'}<details><summary>История Кристаллов</summary>${p.ledger.map(l=>`<p>${l.amount>0?'+':''}${l.amount} 💎 · ${escapeHtml(l.label)} · ${escapeHtml(new Date(l.at).toLocaleDateString('ru-RU'))}</p>`).join('')}</details><p><a href="/signout-with-chatgpt?return_to=%2F" target="_top">Выйти из учетной записи</a></p>`,[{label:'Сокровищница',action:showTreasury},{label:'Скачать мои данные',secondary:true,action:()=>downloadProfile()},{label:'Мои данные / удалить профиль',secondary:true,action:showProfileSettings},{label:'К игре',secondary:true,action:closeModal}]);for(const b of ge('modal-content').querySelectorAll('[data-run]'))b.onclick=()=>Player.restore(p.runs.find(r=>r.id===b.dataset.run));for(const b of ge('modal-content').querySelectorAll('[data-run-journal]'))b.onclick=()=>showArchivedJournal(p.runs.find(r=>r.id===b.dataset.runJournal));for(const b of ge('modal-content').querySelectorAll('[data-reward]'))b.onclick=()=>openOwnedGift(b.dataset.reward);return}
 const ready=Player.economy.privacy.ready;showModal('Моя Точка силы','СОЗДАЙ СВОЙ ПРОФИЛЬ',`<p>Сохраняй осознания, Кристаллы и результаты разных прохождений.</p>${!ready?'<p>Облачный профиль готовится: сначала нужно опубликовать контакт ответственного за сохраненные данные.</p>':!Player.signedIn?'<p><a class="profile-signin" href="/signin-with-chatgpt?return_to=%2F" target="_top">Войти через ChatGPT</a></p><p>Отдельный пароль для игры не нужен.</p>':'<label for="player-name">Как тебя называть?</label><input id="player-name" type="text" maxlength="80" autocomplete="nickname"><label><input type="checkbox" id="profile-consent"> Я согласна на сохранение моих прохождений и истории наград.</label><label><input type="checkbox" id="profile-sensitive"> Я явно согласна на сохранение моих ответов, в том числе чувствительных сведений, которые я сама укажу.</label>'}<button id="profile-privacy" type="button">Как хранятся мои данные?</button>`,[{label:ready&&Player.signedIn?'Создать профиль':'Продолжить как гость',action:async()=>{if(!ready||!Player.signedIn){closeModal();return}if(!ge('profile-consent').checked||!ge('profile-sensitive').checked){announce('Выбери оба согласия для серверного сохранения.');return}try{const d=await Player.api('profile',{method:'POST',body:JSON.stringify({name:ge('player-name').value,consent:true,sensitiveConsent:true,version:Player.economy.privacy.version})});Player.profile=d.profile;await Player.flush();showPlayerProfile()}catch(e){announce(e.message)}}},{label:'К игре',secondary:true,action:closeModal}]);ge('profile-privacy').onclick=showPrivacy}
function showArchivedJournal(run){showModal('Мое прохождение','МОИ ОСОЗНАНИЯ',`<div class="insight-report">${journalHtml(run.journal)}</div>`,[{label:'Распечатать / PDF',action:()=>openJournalPrint(run.journal)},{label:'К профилю',secondary:true,action:showPlayerProfile}])}
function downloadProfile(){const a=document.createElement('a');const url=URL.createObjectURL(new Blob([JSON.stringify(Player.profile,null,2)],{type:'application/json'}));a.href=url;a.download='tochka-sily-my-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),30000)}
function showProfileSettings(){showModal('Мои данные','УПРАВЛЕНИЕ ПРОФИЛЕМ',privacyHtml()+`<label for="profile-new-name">Мое имя</label><input id="profile-new-name" type="text" maxlength="80" value="${escapeHtml(Player.profile.name)}">`,[{label:'Сохранить имя',action:async()=>{try{await Player.api('profile',{method:'POST',body:JSON.stringify({name:ge('profile-new-name').value,consent:true,sensitiveConsent:true,version:Player.economy.privacy.version})});showPlayerProfile()}catch(e){announce(e.message)}}},{label:'Удалить профиль и все данные',secondary:true,action:()=>showModal('Удаление данных','УДАЛИТЬ ПРОФИЛЬ?', '<p>Будут удалены серверные журналы, прохождения, Кристаллы и награды. Скачай данные заранее. Это действие нельзя отменить.</p>',[{label:'Подтверждаю удаление',action:async()=>{try{await Player.api('profile',{method:'DELETE'});Player.profile=null;Player.confirmedRun=0;Player.revision=0;game=defaultGame();profilePersist();localStorage.removeItem(GAME_STORAGE_KEY);closeModal();renderGame();updatePlayerBar()}catch(e){announce(e.message)}}},{label:'Отмена',secondary:true,action:showPlayerProfile}])},{label:'Назад',secondary:true,action:showPlayerProfile}])}
const profilePersist=persist;persist=function(){ensureRun();profilePersist();Player.save()};
const playerBar=document.createElement('nav');playerBar.className='player-bar';playerBar.setAttribute('aria-label','Мои ресурсы и профиль');playerBar.innerHTML='<button id="player-energy" title="Энергия — ресурс этой игры">⚡ Энергия</button><button id="player-crystals">💎 0</button><button id="player-treasury">Сокровищница</button><button id="player-profile">Мой профиль</button><span id="player-mode">Подключение…</span>';document.querySelector('.tabs').before(playerBar);ge('player-treasury').onclick=()=>Player.economy&&showTreasury();ge('player-profile').onclick=()=>Player.economy&&showPlayerProfile();ge('player-crystals').onclick=()=>Player.economy&&showModal('Кристаллы силы','Я НАКАПЛИВАЮ',`<p>Кристаллы сохраняются между играми в профиле. Накапливай их и обменивай на подарки.</p><p>Мой баланс: ${crystalBalance()} 💎</p>${Player.profile?'':'<p>Сейчас ты играешь как гость. Серверный профиль еще не подключен.</p>'}`, [{label:'Посмотреть подарки',action:showTreasury},{label:'К игре',secondary:true,action:closeModal}]);ge('player-energy').onclick=()=>showModal('Энергия','Я НАПРАВЛЯЮ','<p>Энергия собирается во время этой игры. В финале ты направишь ее в свои цели и важные сферы жизни.</p>',singleClose());
fetch('./economy-config.json').then(r=>r.json()).then(async e=>{Player.economy=e;ensureRun();profilePersist();updatePlayerBar();await Player.load();if(Player.profile){const current=Player.profile.runs.find(r=>r.id===game.runId);if(current){Player.revision=current.revision;Player.confirmedRun=runCrystals(current.state)}const latest=Player.profile.runs.find(r=>!r.completed);if(latest&&!game.pendingMovement&&!game.pendingRoll){ge('journey-cinema').hidden=true;SoundManager.stop('intro');showModal('Мой путь','ПРОДОЛЖИТЬ ПУТЬ?',`<p>У тебя есть незавершенная игра.</p><p>Запрос: «${escapeHtml(latest.state.originalRequest)}»</p><p>Пройдено ${(latest.state.completedModules||[]).filter(Boolean).length} из 5 шагов.</p>`,[{label:'Продолжить',action:()=>Player.restore(latest)},{label:'Начать новую игру',secondary:true,action:confirmNewSession}])}}}).catch(()=>{Player.status='offline';ge('player-mode').textContent='Профиль временно недоступен'});
